class Larik {
public:
    int *data;
    int banyak;

    Larik(int n) : data(new int[n]), banyak(n) {
        for (int k = 0; k < n; k++) {
            data[k] = 0;
        }
    }

    Larik(const Larik &lain) : data(new int[lain.banyak]), banyak(lain.banyak) {
        for (int k = 0; k < banyak; k++) {
            data[k] = lain.data[k];
        }
    }

    Larik &operator=(const Larik &lain) {
        if (this != &lain) {
            delete[] data;
            banyak = lain.banyak;
            data = new int[banyak];
            for (int k = 0; k < banyak; k++) {
                data[k] = lain.data[k];
            }
        }
        return *this;
    }

    ~Larik() {
        delete[] data;
    }

    void baca() {
        for (int k = 0; k < banyak; k++) {
            cin >> data[k];
        }
    }

    void cetak() {
        for (int k = 0; k < banyak; k++) {
            cout << data[k] << " ";
        }
        cout << endl;
    }
};

