#include <iostream>
using namespace std;

class DaftarDinamis {
public:
    int *data;
    int banyak;
    int kapasitas;

    DaftarDinamis() : data(new int[1]), banyak(0), kapasitas(1) {
    }

    ~DaftarDinamis() {
        cout << "Bebas " << kapasitas << endl;
        delete[] data;
    }

    void tambah(int x) {
        if (banyak == kapasitas) {
            auto baru = new int[kapasitas * 2];
            for (int k = 0; k < banyak; k++) {
                baru[k] = data[k];
            }
            delete[] data;
            data = baru;
            cout << "Tumbuh " << kapasitas << " -> " << kapasitas * 2 << endl;
            kapasitas *= 2;
        }
        data[banyak] = x;
        banyak++;
    }

    void cetak() {
        cout << "Isi:";
        for (int k = 0; k < banyak; k++) {
            cout << " " << data[k];
        }
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;
    DaftarDinamis daftar;
    for (int k = 0; k < n; k++) {
        int x;
        cin >> x;
        daftar.tambah(x);
    }
    daftar.cetak();
    return 0;
}

