#include <iostream>
using namespace std;

class Matriks {
public:
    int **sel;
    int baris;
    int kolom;

    Matriks(int b, int k) : sel(new int *[b]), baris(b), kolom(k) {
        for (int i = 0; i < baris; i++) {
            sel[i] = new int[kolom];
            for (int j = 0; j < kolom; j++) {
                sel[i][j] = 0;
            }
        }
    }

    Matriks(const Matriks &lain) : sel(new int *[lain.baris]), baris(lain.baris), kolom(lain.kolom) {
