int main() {
    Pelacak *daftar[30];
    auto banyak = 0;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "buat") {
            int v;
            cin >> v;
            daftar[banyak] = new Pelacak(v);
            banyak++;
        } else if (perintah == "salin") {
            int k;
            cin >> k;
            daftar[banyak] = new Pelacak(*daftar[k - 1]);
            banyak++;
        } else if (perintah == "tugas") {
            int a, b;
            cin >> a >> b;
            *daftar[a - 1] = *daftar[b - 1];
        } else if (perintah == "hapus") {
            if (banyak == 0) {
                cout << "kosong" << endl;
            } else {
                banyak--;
                delete daftar[banyak];
            }
        } else {
            cout << "Isi:";
            for (int k = 0; k < banyak; k++) {
                cout << " " << daftar[k]->id << ":" << daftar[k]->nilai;
            }
            cout << endl;
        }
    }
    while (banyak > 0) {
        banyak--;
        delete daftar[banyak];
    }
    return 0;
}
